    conjugation: '无收音名词 + 라도 (차라도)\n有收音名词 + 이라도 (빵이라도)',
    examples: [
      { ko: '차라도 한 잔 드릴까요? 잠깐 기다려 주세요.', zh: '要喝杯茶吗？请稍等一下。', note: '退让：喝杯茶也好' },
      { ko: '밥이 없으면 빵이라도 먹을까요?', zh: '如果没有饭，吃点面包也行吗？', note: '退让：没饭吃面包也行' },
      { ko: '물이라도 마실래요?', zh: '喝点水也好，要喝吗？', note: '退让：喝点水也行' },
    ],
