    conjugation: '词干元音 ㅏ/ㅗ → 아 두다/놓다 (사다→사 두다)\n其他元音 → 어 두다/놓다 (넣다→넣어 두다)\n하다 → 해 두다/놓다',
    examples: [
      { ko: '미리 예약해 뒀어요.', zh: '提前预约好了（留着）。', note: '预先备置：先约好' },
      { ko: '냉장고에 음식을 넣어 뒀어요.', zh: '把食物放进冰箱里存着了。', note: '预先备置：存进冰箱' },
      { ko: '문을 열어 놓았어요.', zh: '把门开着（开了放那儿）。', note: '预先备置：开着门' },
    ],
