    toriTip: '🐰 -아/어 보니까 = "试了之后才发现…"，分享真实体验的黄金句型。"가 보니까 별로였어요"（去了才发现一般般）、"해 보니까 어렵더라고요"（做了才发现挺难）。后面配 -더라고요 更有"亲身体会"的味道。',
