    conjugation: '无收音/ㄹ + ㄹ 만하다 (보다→볼 만하다)\n有收音 + 을 만하다 (먹다→먹을 만하다)',
    examples: [
      { ko: '이 영화는 볼 만해요.', zh: '这部电影值得看。', note: '值得：值得一看' },
      { ko: '이 식당은 한 번 가 볼 만해요.', zh: '这家餐厅值得去一次。', note: '值得：值得一去' },
      { ko: '이 앨범은 들을 만해요. 특히 타이틀곡이 좋아요.', zh: '这张专辑值得听，特别是主打曲很好。', note: '值得：值得一听' },
    ],
    similarPatterns: ['-(으)ㄹ 가치가 있다', '-(으)ㄹ 수 있다'],
    difference: '-(으)ㄹ 만하다 表示"值得做/还不错"的推荐或评价（"볼 만해요"值得看/还挺好看）；-(으)ㄹ 수 있다 是"能做到"的能力/可能（"볼 수 있어요"能看到）。推荐、给评价用 -(으)ㄹ 만하다，说能力用 -(으)ㄹ 수 있다。',
