    toriTip: '🐰 -(으)ㄹ 테니까 = "我来…你就…"，分工合作的贴心句型。"제가 살 테니까 넌 자리 잡아"（我来买单，你去占座）。前半句是我的承诺/意志，后半句让对方安心去做别的事。',
