    conjugation: '动词过去 + (으)ㄴ 김에 (나오다→나온 김에)\n动词现在 + 는 김에 (청소하다→청소하는 김에)',
    examples: [
      { ko: '나온 김에 장도 봤어요.', zh: '趁着出来，顺便买了东西。', note: '趁便：出来顺便买菜' },
      { ko: '청소하는 김에 빨래도 했어요.', zh: '趁着打扫，顺便洗了衣服。', note: '趁便：打扫顺便洗衣' },
      { ko: '한국에 온 김에 좋아하는 가수 콘서트도 봤어요.', zh: '趁着来韩国，顺便看了喜欢的歌手演唱会。', note: '趁便：来韩顺便看演唱会' },
    ],
