    toriTip: '🐰 -(으)ㄴ 김에 = "趁着…顺便…"，精打细算一举两得。"나온 김에 커피도 사 왔어"（出来了顺便买了咖啡）、"온 김에 밥 먹고 가"（来都来了，吃了饭再走）——"来都来了"就是这个句型的精髓。',
