    conjugation: '名词 + 마저（不受收音影响）',
    examples: [
      { ko: '친구마저 연락을 끊었어요.', zh: '连朋友都断联了。', note: '连也：连朋友都断联' },
      { ko: '일도 잃고 돈마저 없어졌어요.', zh: '工作也丢了，连钱也没了。', note: '连也：连钱都没了' },
      { ko: '마지막 기회마저 놓쳤어요.', zh: '连最后的机会都错过了。', note: '连也：连最后机会都错过' },
    ],
