    conjugation: '动词词干 + 기 십상이다',
    examples: [
      { ko: '눈길에서 뛰면 넘어지기 십상이에요.', zh: '雪地里跑很容易摔倒。', note: '容易：容易摔倒' },
      { ko: '급하게 먹으면 체하기 십상이에요.', zh: '吃太急很容易吃坏肚子。', note: '容易：容易积食' },
      { ko: '충동적으로 쇼핑하면 후회하기 십상이에요.', zh: '冲动购物很容易后悔。', note: '容易：容易后悔' },
    ],
    similarPatterns: ['-기 쉽다', '-기 마련이다'],
