    toriTip: '🐰 -스럽다 = 给人某种感觉、有某种味儿。사랑스럽다（可爱）、부담스럽다（有压力）、자연스럽다（自然）、조심스럽다（谨慎）。它把名词变成形容词，表达"看着/感觉像…"。注意按 ㅂ 不规则变：사랑스러워요，别说成 사랑스럽어요。',
